        // 获取剩余点击次数
        function getRemainingClicks() {
            const remainingElement = document.getElementById('remaining-clicks');
            const text = remainingElement.textContent.trim();
            // 提取数字（处理可能的非数字情况）
            const match = text.match(/\d+/);
            return match ? parseInt(match[0]) : 0;
        }

        // 更新剩余次数显示
        function updateRemainingClicks(remaining) {
            document.getElementById('remaining-clicks').textContent = remaining;
        }

        // 检查当前已点击的数量
        function getClickedCount() {
            const checkboxes = document.querySelectorAll('.maze-checkbox');
            let count = 0;
            checkboxes.forEach(checkbox => {
                if (checkbox.checked) count++;
            });
            return count;
        }

        // 禁用所有剩余的问号
        function disableRemainingQuestions() {
            const container = document.querySelector('.maze-container');
            container.classList.add('max-clicks-reached');

            // 标记已点击的区域
            const checkboxes = document.querySelectorAll('.maze-checkbox');
