                if (checkbox.checked) {
                    const targetId = checkbox.getAttribute('for') || checkbox.id;
                    const areaNumber = targetId.replace('checkbox', '');
                    const area = document.querySelector(`.area${areaNumber}`);
                    if (area) {
                        area.classList.add('clicked');
                    }
                }
            });
        }

        // 页面加载完成后初始化
        document.addEventListener('DOMContentLoaded', function() {
            const maxClicks = getRemainingClicks();
            const checkboxes = document.querySelectorAll('.maze-checkbox');

            // 为每个复选框添加事件监听器
            checkboxes.forEach(checkbox => {
                checkbox.addEventListener('change', function() {
                    const clickedCount = getClickedCount();
                    const remaining = Math.max(0, maxClicks - clickedCount);

                    // 更新显示的剩余次数
                    updateRemainingClicks(remaining);

                    // 如果达到最大点击次数，禁用所有剩余问号
                    if (remaining === 0) {
                        disableRemainingQuestions();
                    }
                });
            });
        });
